'use strict';
const $=s=>document.querySelector(s),owner=KashierData.userId();let snapshot=null,busy=false,request=0;
const active=()=>KashierData.loggedIn()&&KashierData.userId()===owner;
function controls(){$('#expiry-load').disabled=busy;$('#expiry-print').disabled=$('#expiry-csv').disabled=busy||!snapshot||!active();$('#expiry-days').disabled=$('#expiry-mode').value!=='upcoming';}
function clear(){snapshot=null;$('#expiry-sheet').hidden=true;$('#expiry-rows').replaceChildren();$('#expiry-meta').textContent='';for(const k of ['count','expired','today','upcoming'])$('#expiry-'+k).textContent='';controls();}
function invalidate(){request++;clear();$('#expiry-status').textContent='بۆ گەڕانی نوێ لیستەکە دووبارە ئامادە بکە.';}
function node(tag,text){const e=document.createElement(tag);e.textContent=String(text);return e;}
function render(s){$('#expiry-meta').textContent=new Intl.DateTimeFormat('ckb-IQ-u-ca-gregory-nu-latn',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'medium'}).format(new Date(s.generated_at))+' · '+s.today+' · '+(s.query||'هەموو ناوەکان')+' · '+({expired:'بەسەرچوو',today:'ئەمڕۆ',upcoming:'تا '+s.days+' ڕۆژ',all:'هەموو بەروارەکان'})[s.mode]+' · '+(s.include_empty?'لەگەڵ بێ کۆگا':'تەنها بە کۆگا');$('#expiry-count').textContent=s.count;for(const k of ['expired','today','upcoming'])$('#expiry-'+k).textContent=s.counts[k];for(const r of s.rows){const row=document.createElement('tr');for(const text of [r.name,r.barcode||'—',r.expiry_date])row.append(node('td',text));const stage=node('td',Expiry.stages[r.stage]+(r.days_left>0?' · '+r.days_left+' ڕۆژ':''));stage.className='expiry-stage-'+r.stage;row.append(stage,node('td',Expiry.quantity(r.quantity_units)));const action=document.createElement('td'),edit=node('a','دەستکاری بەروار'),profile=node('a','کارتی کاڵا');action.className='no-print';edit.href='products.html?edit='+r.id;profile.href='product.html?id='+r.id;action.append(edit,profile);row.append(action);$('#expiry-rows').append(row);}$('#expiry-none').hidden=s.count!==0;$('#expiry-sheet').hidden=false;}
$('#expiry-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;clear();if(!active()){location.replace('auth.html?next=expiry.html');return;}const mine=++request;try{const mode=$('#expiry-mode').value,days=mode==='upcoming'?Number($('#expiry-days').value):30,query=$('#expiry-query').value.trim(),includeEmpty=$('#expiry-empty').checked;if(!Number.isSafeInteger(days)||days<1||days>365)throw Error('سنوورێکی دروست لە ١ تا ٣٦٥ ڕۆژ بنووسە.');const f={mode,days,query,includeEmpty};busy=true;controls();$('#expiry-status').textContent='ئامادەکردنی لیستی بەسەرچوون…';const s=await KashierData.getExpiryReport(f);if(mine!==request)return;if(!active())throw Error('هەژمارەکە گۆڕاوە؛ دووبارە بچۆ ژوورەوە.');Expiry.validate(s,f);snapshot=s;render(s);$('#expiry-status').textContent='لیستی یادخستنەوە ئامادەیە.';}catch(error){if(mine===request){clear();$('#expiry-status').textContent=(globalThis.KashierLocale?.message(error.message)??error.message);}}finally{busy=false;controls();}});
for(const [id,event] of [['mode','change'],['days','input'],['query','input'],['empty','change']])$('#expiry-'+id).addEventListener(event,invalidate);
function usable(){if(!active()){clear();$('#expiry-status').textContent='هەژمارەکە گۆڕاوە؛ لیست دووبارە ئامادە بکە.';return false;}return !busy&&Boolean(snapshot);}
$('#expiry-print').addEventListener('click',()=>{if(usable())window.print();});$('#expiry-csv').addEventListener('click',()=>{if(!usable())return;const url=URL.createObjectURL(new Blob([Expiry.csv(snapshot)],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='kashier-expiry-'+snapshot.today+'.csv';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});window.addEventListener('pagehide',()=>{request++;clear();});window.addEventListener('pageshow',e=>{if(e.persisted)invalidate();});clear();if(!active())location.replace('auth.html?next=expiry.html');
